-- 063_backfill_hk_drinks.sql
--
-- HK Drinks (Cincoro / Clase Azul) rows enriched from the supplier's OWN
-- product pages at hkdrinks.shop — the "no ecommerce feed" case. Data is
-- their own listing copy + ABV; origin Mexico is the documented source of
-- both brands (Jalisco). Descriptions capped at ~48 words.
-- Generated by scripts/extract_hkdrinks_products.py — DO NOT hand-edit.
--
-- NOTE for review: the Clase Azul page copy appears templated from the
-- Cincoro page (differs only by brand name), and its Plata blurb calls the
-- bottle a "cristalino expression", which is not accurate for a Plata.
-- Imported as supplied, but worth correcting on hkdrinks.shop.

-- Cincoro Collection  <-  brand collection page (cincoro.html#cincoro)
UPDATE drinks SET origin = 'Mexico', buy_url = 'https://hkdrinks.shop/cincoro'
WHERE supplier_name = 'HK Drinks' AND name = 'Cincoro Collection';

-- Cincoro Blanco Tequila  <-  Cincoro Blanco (cincoro.html#cincoro-plata)
UPDATE drinks SET description = 'Unaged, crystal clear plata capturing the pure essence of Blue Weber Agave with notes of citrus, herbs, and a silky smooth finish. The cristalino expression that defines the Cincoro standard.', abv = '40%', origin = 'Mexico', buy_url = 'https://hkdrinks.shop/cincoro#cincoro-plata'
WHERE supplier_name = 'HK Drinks' AND name = 'Cincoro Blanco Tequila';

-- Cincoro Reposado Tequila  <-  Cincoro Reposado (cincoro.html#cincoro-reposado)
UPDATE drinks SET description = 'A reposado tequila aged in American whiskey barrels. The iconic beautifully designed bottle with beautifully styled blue design, the most recognisable tequila bottle in the world. Notes of vanilla, caramel, and toasted oak.', abv = '40%', origin = 'Mexico', buy_url = 'https://hkdrinks.shop/cincoro#cincoro-reposado'
WHERE supplier_name = 'HK Drinks' AND name = 'Cincoro Reposado Tequila';

-- Cincoro Gold Tequila  <-  Cincoro Gold (cincoro.html#cincoro-gold)
UPDATE drinks SET description = 'A masterful blend of reposado and extra añejo, presented in a stunning gold-accented bottle. Warm honey, oak spice, dried fruits, with a finish that lingers beautifully.', abv = '40%', origin = 'Mexico', buy_url = 'https://hkdrinks.shop/cincoro#cincoro-gold'
WHERE supplier_name = 'HK Drinks' AND name = 'Cincoro Gold Tequila';

-- Cincoro Anejo Tequila  <-  Cincoro Añejo (cincoro.html#cincoro-anejo)
UPDATE drinks SET description = 'An extra añejo tequila aged in American whiskey barrels. Rich notes of dark chocolate, dried cherry, vanilla, and clove. Presented in a beautifully presented bottle that reflects the liquid''s extraordinary depth.', abv = '40%', origin = 'Mexico', buy_url = 'https://hkdrinks.shop/cincoro#cincoro-anejo'
WHERE supplier_name = 'HK Drinks' AND name = 'Cincoro Anejo Tequila';

-- Cincoro Extra Anejo Tequila  <-  Cincoro Extra Anejo (cincoro.html#cincoro-ultra)
UPDATE drinks SET description = 'An extra añejo tequila aged in American oak casks with a finish in Pedro Ximénez sherry casks. Limited-edition elegant bottle with 24K gold accents. Extraordinary notes of figs, dates, dark chocolate, and a finish that seems to last forever.', abv = '40%', origin = 'Mexico', buy_url = 'https://hkdrinks.shop/cincoro#cincoro-ultra'
WHERE supplier_name = 'HK Drinks' AND name = 'Cincoro Extra Anejo Tequila';

-- Clase Azul Plata  <-  Clase Azul Plata (clase-azul.html#clase-azul-plata)
UPDATE drinks SET description = 'Unaged, crystal clear plata capturing the pure essence of Blue Weber Agave with notes of citrus, herbs, and a silky smooth finish. The cristalino expression that defines the Clase Azul standard.', abv = '40%', origin = 'Mexico', buy_url = 'https://hkdrinks.shop/clase-azul#clase-azul-plata'
WHERE supplier_name = 'HK Drinks' AND name = 'Clase Azul Plata';

-- Clase Azul Reposado  <-  Clase Azul Reposado (clase-azul.html#clase-azul-reposado)
UPDATE drinks SET description = 'A reposado tequila aged in American whiskey barrels. The iconic matte white decanter with hand-painted blue design, the most recognisable tequila bottle in the world. Notes of vanilla, caramel, and toasted oak.', abv = '40%', origin = 'Mexico', buy_url = 'https://hkdrinks.shop/clase-azul#clase-azul-reposado'
WHERE supplier_name = 'HK Drinks' AND name = 'Clase Azul Reposado';

-- Clase Azul Gold  <-  Clase Azul Gold (clase-azul.html#clase-azul-gold)
UPDATE drinks SET description = 'A masterful blend of reposado and extra añejo, presented in a stunning gold-decorated decanter. Warm honey, oak spice, dried fruits, with a finish that lingers beautifully.', abv = '40%', origin = 'Mexico', buy_url = 'https://hkdrinks.shop/clase-azul#clase-azul-gold'
WHERE supplier_name = 'HK Drinks' AND name = 'Clase Azul Gold';

-- Clase Azul Anejo  <-  Clase Azul Añejo (clase-azul.html#clase-azul-anejo)
UPDATE drinks SET description = 'An extra añejo tequila aged in American whiskey barrels. Rich notes of dark chocolate, dried cherry, vanilla, and clove. Presented in a deep blue hand-painted decanter that reflects the liquid''s extraordinary depth.', abv = '40%', origin = 'Mexico', buy_url = 'https://hkdrinks.shop/clase-azul#clase-azul-anejo'
WHERE supplier_name = 'HK Drinks' AND name = 'Clase Azul Anejo';

